    input [49:0] in,
    input select,
    input load,
    input enable,
    output reg [49:0] q
);reg [49:0] rotator_out;
    reg [49:0] comb_out;
    reg [49:0] sub_out;
    reg [49:0] in_reg;
    reg [49:0] rotator_in;

    always @(posedge clk) begin
        if (reset) begin
            in_reg <= 50'b0;
            q <= 50'b0;
            rotator_in <= 50'b0;
