                comb_out <= ~(in_reg[0] | in_reg[1] | in_reg[2] | in_reg[3]);
                rotator_out <= rotator_in;
                sub_out <= comb_out - rotator_out;
                q <= sub_out;
            end
        end
    end

endmodule

