module top_module(
    in,
    clk,
    rst_n,  
    rst     
);input in;   
    input clk; 
    input rst_n;
    output rst;

    reg rst;
    reg [7:0]cnt;
    reg [7:0]cnt_tmp0;
    reg [7:0]cnt_tmp1;

    always @*
    if (in == 1'b1)
        cnt_tmp0 = cnt + 1;
    else
        cnt_tmp0 = 7'b0;

    always @*
    if (cnt_tmp0 == 7'd100)
    begin
        rst = 1;
        cnt_tmp1 = 7'b0;
    end
    else
    begin
        rst = 0;
        cnt_tmp1 = cnt_tmp0;
    end
    always @(posedge clk or negedge rst_n)
    if (~rst_n)
        cnt <= 0;
    else
        cnt <= cnt_tmp1;

endmodule

