Implement the Verilog module based on the following description.
Build an 8-bit shift register with parallel load and enable.
// (1) data: Parallel data input.
// (2) enable: Enables the shift operation. Active high.
// (3) load: Parallel load enable. Active high.
// (4) clk: Clock signal.
// (5) q: 8-bit output of the shift register.
module top_module(
	input [7:0] data,
	input enable,
	input load,
	input clk,
	output reg [7:0] q);

code:
module top_module(
	input [7:0] data,
	input enable,
	input load,
	input clk,
	output reg [7:0] q);always @(posedge clk) begin
	if (load)
		q <= data;
	else if (enable)
		q <= {q[6:0], 1'b0};
end
endmodule

