description:
Design a 4-bit binary comparator that determines the larger of two input numbers, `num1` and `num2`. The module contains two pipeline stages to register the inputs before comparison. It outputs the larger number through the `larger_num` output signal, ensuring that the comparison is based on registered values rather than immediate inputs.
module top_module(
    input [3:0] num1,
    input [3:0] num2,
    output reg [3:0] larger_num
);

code:
module top_module(
    input [3:0] num1,
    input [3:0] num2,
    output reg [3:0] larger_num
);reg [3:0] pipeline_reg1;
reg [3:0] pipeline_reg2;

// Pipeline stage 1
always @(num1) begin
    pipeline_reg1 <= num1;
end

// Pipeline stage 2
always @(num2) begin
    pipeline_reg2 <= num2;
end

// Comparator module
always @(*) begin
    if (pipeline_reg1 > pipeline_reg2) begin
        larger_num <= pipeline_reg1;
    end else begin
        larger_num <= pipeline_reg2;
    end
end

endmodule

