    top_module dut (
        .clk(clk),
        .enable_clk(enable_clk),
        .reset(reset),
        .falling_edge(falling_edge),
        .middle_of_high_level(middle_of_high_level),
        .middle_of_low_level(middle_of_low_level),
        .new_clk(new_clk),
        .rising_edge(rising_edge)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            enable_clk = 0;
            @(posedge clk);
            #2;
            reset = 0;
            @(posedge clk);
            #2;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            reset_dut();
            #1;

            check_outputs(0, 0, 0, 0, 0);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            reset_dut();
            enable_clk = 1;
            #2;
            #1;

            check_outputs(0, 0, 0, 1, 1);
            @(posedge clk);
            enable_clk = 0;
            #1;
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            reset_dut();

            enable_clk = 1; @(posedge clk); #2;

            enable_clk = 1;
            #2;
            #1;

            check_outputs(0, 1, 0, 1, 0);
            @(posedge clk);
            enable_clk = 0;
            #1;
