description:
Design a clock divider that generates a slower clock signal derived from an input clock. The module uses a 3-bit counter to count clock cycles, toggling two registers at specific counts to create two different phase outputs. This results in an output clock signal that is the exclusive OR of the two toggled signals, effectively producing a clock that transitions at a reduced rate and can be used for timing adjustments in digital circuits. The module also includes a reset functionality to initialize the counter and toggle states.
module top_module(
  input  i_clk,
  input  i_rstn,
  output o_clk
);

code:
module top_module(
  input  i_clk,
  input  i_rstn,
  output o_clk
);reg [2:0] r_cnt;
  wire      w_slow_0, w_slow_90;
  reg       r_toggle_0, r_toggle_90;


  always @(posedge i_clk, negedge i_rstn) begin
    if (!i_rstn) begin
      r_cnt <= 0;
    end else begin
      r_cnt <= (r_cnt == 4) ? 0 : r_cnt + 1;
    end
  end


  assign w_slow_0  = (r_cnt == 0) ? 1 : 0;
  assign w_slow_90 = (r_cnt == 3) ? 1 : 0;


  always @(posedge i_clk, negedge i_rstn) begin
    if (!i_rstn) begin
      r_toggle_0 <= 0;
    end else begin
      r_toggle_0 <= (w_slow_0 == 1) ? ~r_toggle_0 : r_toggle_0;
    end
  end


  always @(negedge i_clk, negedge i_rstn) begin
    if (!i_rstn) begin
      r_toggle_90 <= 0;
    end else begin
      r_toggle_90 <= (w_slow_90 == 1) ? ~r_toggle_90 : r_toggle_90;
    end
  end


  assign o_clk = r_toggle_0 ^ r_toggle_90;

endmodule

