description:
Design a clock divider module that takes an input clock signal and generates an output clock signal with a reduced frequency. When the specified division factor \( N \) is set (default is 5), the module counts clock cycles on both the positive and negative edges of the input clock. It generates two intermediate clock signals, `clk_p` and `clk_n`, which together produce the final `clk_out` signal based on the count values, effectively dividing the input frequency by a factor of \( N \). The reset control (`rst_n`) ensures that the counters and clock outputs can be reset to their initial states.
module top_module(
	clk,
	rst_n,
	clk_out
	);

code:
module top_module(
	clk,
	rst_n,
	clk_out
	);parameter WIDTH = 3;
	parameter N = 5;

	input  clk, rst_n;
	output clk_out;

	reg 	[WIDTH-1:0]		cnt_p,cnt_n;
	reg						clk_p,clk_n;

	assign clk_out = (N==1)?clk:(N[0])?(clk_p&clk_n):clk_p;

	always @ (posedge clk)
		begin
			if(!rst_n)
				cnt_p<=0;
			else if (cnt_p==(N-1))
				cnt_p<=0;
			else cnt_p<=cnt_p+1;
		end

	always @ (negedge clk)
		begin
			if(!rst_n)
				cnt_n<=0;
			else if (cnt_n==(N-1))
				cnt_n<=0;
			else cnt_n<=cnt_n+1;
		end

	always @ (posedge clk)
		begin
			if(!rst_n)
				clk_p<=0;
			else if (cnt_p<(N>>1))  
				clk_p<=0;
			else 
				clk_p<=1;
		end

	always @ (negedge clk)
		begin
			if(!rst_n)
				clk_n<=0;
			else if (cnt_n<(N>>1))  
				clk_n<=0;
			else 
				clk_n<=1;
		end
endmodule

