description:
Design a state machine that processes a sequence of operations through four distinct states: start_bit, data_bit, parity, and stop_bit. In the data_bit state, it counts from 0 to 7, enabling the 'en' output while counting. Once it reaches the maximum count, it transitions to the parity state, where 'en' is disabled and transitions to the stop_bit state, before returning to the start_bit state. The 'done' output indicates when the machine is in the start_bit state. This module is intended for sequential logic applications where data transmission and state transitions are managed cyclically.
module top_module(
	input wire clk,
	output wire done,
	output reg en
);

code:
module top_module(
	input wire clk,
	output wire done,
	output reg en
);reg [1:0] state, nstate;
	reg [3:0] count;
	localparam start_bit = 2'b00, data_bit = 2'b01, parity = 2'b10, stop_bit = 2'b11;

	assign done = (state == 2'b00);

	always @ (*)
	begin
		state = nstate;		
	end

	always @ (negedge clk)	
	begin
		case (state)		
		start_bit: 		
			begin
				nstate <= data_bit;		
				en <= 1'b1;			
			end

		data_bit:	
			begin	
				if (count < 4'b0111)	
				begin
					en <= 1'b1;			
					count <= count + 1'b1;
				end
				else
				begin
					en <= 1'b0;			
					count <= 4'b0000;
					nstate <= parity;
				end
			end

		parity:	
			begin		
				nstate <= stop_bit;
				en <= 1'b0;
			end

		stop_bit:	
			begin		
				nstate <= start_bit;
				en <= 1'b0;
			end

		default:
			begin	
				nstate <= start_bit;	
				count <= 4'b0000;		
				en <= 1'b0;				
			end
		endcase
	end
endmodule

