description:
Implement the Verilog module based on the following description.
Build a 3-bit binary counter with asynchronous active low reset signal.
// (1) reset_n: Asynchronously resets the counter to zero.
// (2) q: The value of the counter.

module binary_counter(
    input clk,
    input reset_n,
    output reg [2:0] q);

code:
module binary_counter(
    input clk,
    input reset_n,
    output reg [2:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to zero
            q <= 3'b000;
        end else begin
            // Increment the counter by 1
            q <= q + 1;
        end
    end

endmodule

