description:
Design a D flip-flop with asynchronous active-low reset functionality. When the RESET_B signal is low, the output Q is set to 0 regardless of the D input. On the rising edge of D, if RESET_B is high, the output Q takes the value of D, effectively capturing the input.
module top_module(
    input D,
    input RESET_B,
    output Q
);

code:
module top_module(
    input D,
    input RESET_B,
    output Q
);reg Q_reg;

    always @(posedge D, negedge RESET_B) begin
        if (!RESET_B) begin
            Q_reg <= 1'b0;
        end else begin
            Q_reg <= D;
        end
    end

    assign Q = Q_reg;

endmodule

